import { expect, expectStatus, test } from "../../fixtures";

test("Vendors from another tenant are invisible", { tag: "@VEN-07" }, async ({ apiAs, factory }) => {
  // Arrange: otherTenant is member@globex.test, seeded in tenant "Globex Procurement".
  const globexVendor = await factory.vendor({ as: "otherTenant" });
  const member = await apiAs("member");

  // Act
  const response = await member.get(`/api/vendors/${globexVendor.id}`);

  // Assert
  const body = await expectStatus(response, 404);
  expect(body.error.code).toBe("vendor_not_found");
});
